 *
 * @param order 배송 완료된 주문 (COMPLETED로 바꾸기 전 상태여야 함)
 */
private void grantPurchasePoints(Order order) {
    if (order.getStatus() == OrderStatus.COMPLETED) {
        log.debug("이미 완료된 주문이므로 구매 적립 생략: orderId={}", order.getId());
        return;
    }

    int points = order.getTotalAmount() / 100;
    if (points <= 0) {
        log.debug("적립 포인트가 0이므로 구매 적립 생략: orderId={}, totalAmount={}",
                order.getId(), order.getTotalAmount());
        return;
    }

    User buyer = order.getUser();
    pointCommandService.addPoint(buyer.getEmail(), PointDto.AddPointRequest.builder()
            .amount(points)
            .reason("구매 적립 (주문 ID: " + order.getId() + ")")
            .build());

    notificationCommandService.createNotification(
            buyer.getId(),
            NotificationCategory.SHOPPING,
            NotificationType.BENEFIT,
            String.format("구매 적립 %,dP가 지급되었습니다. 주문 ID: %d", points, order.getId())
    );

    log.info("구매 적립 완료: userId={}, orderId={}, points={}", buyer.getId(), order.getId(), points);
}

